SELECT CASE WHEN quantity >= 252 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, STDDEV_SAMP(quantity) AS quantity_stddev, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, BIT_OR(quantity) AS quantity_bit_or, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles_2 FROM inventory GROUP BY CASE WHEN quantity >= 252 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY quantity_tier DESC;
